local WorldMap = {}

-- ─────────────────────────────────────────────────────────────────────────────
-- Scanline polygon fill
-- ring: flat {x1,y1,x2,y2,...} table (integer coords)
-- ─────────────────────────────────────────────────────────────────────────────
local function fillRing( pix, ring, W, H, r, g, b, sx, sy )
        sx = sx or 1
        sy = sy or 1
        local n = math.floor( #ring / 2 )
        if n < 3 then return end

        -- Bounding box (y-axis) — scale coords on the fly
        local ylo, yhi = H, 0
        for i = 0, n - 1 do
                local y = ring[ i * 2 + 2 ] * sy
                if y < ylo then ylo = y end
                if y > yhi then yhi = y end
        end
        ylo = math.max( 0, math.floor( ylo ) )
        yhi = math.min( H - 1, math.floor( yhi ) )

        for y = ylo, yhi do
                -- Collect x-crossings for this scanline
                local xs   = {}
                local cnt  = 0
                local px   = ring[ (n - 1) * 2 + 1 ] * sx
                local py   = ring[ (n - 1) * 2 + 2 ] * sy
                for vi = 1, n do
                        local cx = ring[ (vi - 1) * 2 + 1 ] * sx
                        local cy = ring[ (vi - 1) * 2 + 2 ] * sy
                        if (py <= y and cy > y) or (cy <= y and py > y) then
                                -- Compute x at this scanline
                                local xc = px + (y - py) * (cx - px) / (cy - py)
                                cnt = cnt + 1
                                xs[ cnt ] = xc
                        end
                        px = cx
                        py = cy
                end
                table.sort( xs )
                -- Fill between pairs
                local xi = 1
                while xi < cnt do
                        local x1 = math.max( 0, math.ceil(  xs[ xi     ] ) )
                        local x2 = math.min( W - 1, math.floor( xs[ xi + 1 ] ) )
                        for x = x1, x2 do
                                local o = ( y * W + x ) * 3 + 1
                                pix[o] = r;  pix[o+1] = g;  pix[o+2] = b
                        end
                        xi = xi + 2
                end
        end
end

local function fillPolys( pix, rings, W, H, r, g, b, sx, sy )
        for _, ring in ipairs( rings ) do
                fillRing( pix, ring, W, H, r, g, b, sx, sy )
        end
end

-- ─────────────────────────────────────────────────────────────────────────────
-- 8-bit XOR table and CRC32
-- ─────────────────────────────────────────────────────────────────────────────
local _XB = {}
for _a = 0, 255 do
        local row = {}
        for _b = 0, 255 do
                local xv, a2, b2, bit = 0, _a, _b, 1
                while bit < 256 do
                        if a2 % 2 ~= b2 % 2 then xv = xv + bit end
                        a2 = math.floor( a2 / 2 )
                        b2 = math.floor( b2 / 2 )
                        bit = bit * 2
                end
                row[_b] = xv
        end
        _XB[_a] = row
end

local function x32( a, b )
        return _XB[ math.floor(a/16777216)      ][ math.floor(b/16777216)       ] * 16777216
             + _XB[ math.floor(a/65536)   % 256 ][ math.floor(b/65536)   % 256  ] *    65536
             + _XB[ math.floor(a/256)     % 256 ][ math.floor(b/256)     % 256  ] *      256
             + _XB[             a         % 256 ][             b         % 256   ]
end

local _POLY32 = 3988292384
local _CT = {}
for _n = 0, 255 do
        local c = _n
        for _ = 1, 8 do
                if c % 2 == 1 then c = x32( _POLY32, math.floor(c/2) )
                else c = math.floor(c/2) end
        end
        _CT[_n] = c
end

local _MASK32 = 4294967295
local function crc32str( s )
        local crc = _MASK32
        for i = 1, #s do
                crc = x32( _CT[ _XB[crc%256][s:byte(i)] ], math.floor(crc/256) )
        end
        return x32( crc, _MASK32 )
end

-- ─────────────────────────────────────────────────────────────────────────────
-- PNG helpers
-- ─────────────────────────────────────────────────────────────────────────────
local function u32be( n )
        return string.char(
                math.floor(n/16777216)%256,
                math.floor(n/65536)%256,
                math.floor(n/256)%256,
                n%256 )
end

local function pngChunk( typ, dat )
        return u32be(#dat) .. typ .. dat .. u32be( crc32str( typ .. dat ) )
end

-- ─────────────────────────────────────────────────────────────────────────────
-- Cache
-- ─────────────────────────────────────────────────────────────────────────────
local function enabledHash( enabledSet )
        local ids = {}
        for id in pairs( enabledSet ) do ids[#ids+1] = id end
        table.sort( ids )
        return table.concat( ids, "," )
end

-- Short deterministic slug of the enabled-set string (djb2, kept in 32-bit).
-- The generated PNG filename embeds this slug, which gives us two things for free:
--   • a persistent cross-session cache (a given selection always maps to the same
--     file, reused across Lightroom restarts — no regeneration when unchanged), and
--   • a distinct file path per selection, so the LrView picture reliably reloads
--     when the map is regenerated for a changed selection.
local function slugOf( s )
        local h = 5381
        for i = 1, #s do
                h = ( h * 33 + s:byte(i) ) % 4294967296
        end
        return string.format( "%08x", h )
end

-- Bump MAP_REV whenever polygons are added/changed so stale cached PNGs
-- (rendered before a country existed on the map) are not reused.
local MAP_REV = "3"

local function mapPathFor( enabledSet )
        local slug = slugOf( MAP_REV .. "|" .. enabledHash( enabledSet ) )
        return LrPathUtils.child( _PLUGIN.path, "lr_geography_map_900_" .. slug .. ".png" )
end

local function fileExists( path )
        local fh = io.open( path, "rb" )
        if fh then fh:close(); return true end
        return false
end

-- ─────────────────────────────────────────────────────────────────────────────
-- WorldMap.getCachedPath( enabledSet ) → png_path or nil   (NEVER generates)
-- Returns the already-rendered map file for this selection if it exists on disk.
-- Cheap: a single file-existence check. Used to show the map instantly on dialog
-- open without ever triggering the heavy (~75 s) render.
-- ─────────────────────────────────────────────────────────────────────────────
function WorldMap.getCachedPath( enabledSet )
        local p = mapPathFor( enabledSet )
        if fileExists( p ) then return p end
        return nil
end

-- ─────────────────────────────────────────────────────────────────────────────
-- WorldMap.generate( enabledSet ) → png_path or nil
-- Heavy (~75 s in Lightroom's Lua). Now only called on demand ("Update map"),
-- never automatically on dialog open. If the map for this exact selection already
-- exists on disk, it is reused immediately (persistent cross-session cache).
-- ─────────────────────────────────────────────────────────────────────────────
function WorldMap.generate( enabledSet )

        local outPath = mapPathFor( enabledSet )

        -- Persistent cross-session cache: the filename encodes the selection, so an
        -- existing file always matches this exact selection — reuse it and skip the
        -- expensive render (also true across Lightroom restarts).
        if fileExists( outPath ) then return outPath end

        local W, H = 900, 450
        local sx, sy = 1.5, 1.5

        -- Pixel buffer (1-indexed flat array: R,G,B,R,G,B,...)
        local pix = {}

        -- Ocean fill
        local R_O, G_O, B_O = 173, 216, 230
        local total = W * H * 3
        local ii = 1
        while ii <= total do
                pix[ii]=R_O; pix[ii+1]=G_O; pix[ii+2]=B_O; ii=ii+3
        end

        -- All other land (grey)
        fillPolys( pix, _PO, W, H, 185, 185, 185, sx, sy )

        -- Plugin countries (steel blue)
        local R_P, G_P, B_P = 100, 160, 210
        local ORDER = {"Norway","Sweden","UnitedStates","Panama","Chile","Kenya","NewZealand","Greenland","Finland","UnitedKingdom","India","Argentina","Antarctica","Australia","Rwanda","SouthAfrica","Ecuador","Botswana","Bulgaria","Hungary","Netherlands","China","Croatia","Russia","France","Denmark","Iceland","Germany","Spain","Portugal","Italy","Austria","Belgium","Switzerland","Ireland","Poland","Greece","CzechRepublic","Romania","Serbia","Slovakia","Slovenia","Estonia","Latvia","Lithuania","Ukraine","Albania","BosniaAndHerzegovina","Montenegro","NorthMacedonia","Venezuela","Brazil","Paraguay","Uruguay","Colombia","Peru","Cuba","Guatemala","Belize","ElSalvador","Nicaragua","Bolivia","Jamaica","Haiti","DominicanRepublic","Bahamas","Guyana","Surinam","Canada","Mexico","Honduras","CostaRica","Egypt","Morocco","Tunisia","Nigeria","Ghana","Senegal","Tanzania","Ethiopia","Uganda","Namibia","Moldova","Belarus","Turkey","Luxembourg","Malta","Israel","Cyprus","Andorra","Monaco","SanMarino","Liechtenstein","Vatican","Japan","Thailand","Jordan","Nepal","SriLanka","Indonesia","Vietnam","Philippines","Malaysia","SouthKorea","Cambodia","UnitedArabEmirates","Fiji"}
        for _, pid in ipairs( ORDER ) do
                local rings = _PP[pid]
                if rings then fillPolys( pix, rings, W, H, R_P, G_P, B_P, sx, sy ) end
        end

        -- Enabled countries (red) — painted on top
        local R_E, G_E, B_E = 210, 80, 80
        for _, pid in ipairs( ORDER ) do
                if enabledSet[pid] then
                        local rings = _PP[pid]
                        if rings then fillPolys( pix, rings, W, H, R_E, G_E, B_E, sx, sy ) end
                end
        end

        -- ── Adler-32 and raw rows ────────────────────────────────────────────
        local ROW_BYTES = 1 + W * 3   -- filter byte + pixels
        local s1, s2 = 1, 0
        local rawRows = {}
        local lenLo  = ROW_BYTES % 256
        local lenHi  = math.floor( ROW_BYTES / 256 ) % 256
        local nlenLo = 255 - lenLo
        local nlenHi = 255 - lenHi
        local hdrN   = string.char( 0, lenLo, lenHi, nlenLo, nlenHi )
        local hdrL   = string.char( 1, lenLo, lenHi, nlenLo, nlenHi )

        local blocks = {}
        local sc = string.char

        for y = 0, H - 1 do
                s2 = s2 + s1              -- filter byte 0 (value 0: s1 unchanged)
                local parts = {"\0"}
                local pn    = 1
                local base  = y * W * 3
                for x = 0, W - 1 do
                        local o  = base + x * 3 + 1
                        local rv = pix[o]
                        local gv = pix[o+1]
                        local bv = pix[o+2]
                        pn = pn + 1
                        parts[pn] = sc( rv, gv, bv )
                        s1 = s1 + rv; s2 = s2 + s1
                        s1 = s1 + gv; s2 = s2 + s1
                        s1 = s1 + bv; s2 = s2 + s1
                end
                -- Defer the Adler-32 modulo to once per row instead of per channel.
                -- One row is 2701 bytes, so the running sums stay far below 2^53 and
                -- the result is bit-identical — this removes ~2.4M modulo ops per map.
                s1 = s1 % 65521
                s2 = s2 % 65521
                local rowStr = table.concat( parts )
                if y == H - 1 then
                        blocks[#blocks+1] = hdrL .. rowStr
                else
                        blocks[#blocks+1] = hdrN .. rowStr
                end
        end

        local adlerStr   = u32be( s2 * 65536 + s1 )
        local zlibStream = "\120\001" .. table.concat( blocks ) .. adlerStr

        local ihdr = u32be(W) .. u32be(H) .. "\8\2\0\0\0"
        local png  = "\137\80\78\71\13\10\26\10"
                  .. pngChunk( "IHDR", ihdr )
                  .. pngChunk( "IDAT", zlibStream )
                  .. pngChunk( "IEND", "" )

        -- Write
        local ok = pcall(function()
                local fh = io.open( outPath, "wb" )
                if not fh then error("cannot open " .. tostring(outPath)) end
                fh:write( png )
                fh:close()
        end)

        if ok then return outPath end
        return nil

end  -- WorldMap.generate

