function WorldMap.generateHTML( enabledSet )
        local supParts, enaParts = {}, {}
        for id, code in pairs( ISO ) do
                supParts[#supParts+1] = tostring(code)
                if enabledSet[id] then enaParts[#enaParts+1] = tostring(code) end
        end
        table.sort(supParts); table.sort(enaParts)

        local html = [==[
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Geography Keyword Builder — World Map</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
       background:#1c2b3a;color:#e8edf2;height:100vh;display:flex;
       flex-direction:column;overflow:hidden}
  #hdr{padding:10px 18px;background:#16273a;border-bottom:1px solid #2a4560;flex-shrink:0}
  #hdr h1{font-size:15px;font-weight:600}
  #hdr p{font-size:12px;color:#8aabb0;margin-top:2px}
  #mw{flex:1;overflow:hidden;position:relative}
  svg{display:block;width:100%;height:100%}
  .ocean{fill:#2a6080}
  .grat{fill:none;stroke:#1e4a62;stroke-width:0.4}
  .land{fill:#9ba8b5;stroke:#d0d8e0;stroke-width:0.35}
  .sup{fill:#4a8fd4;stroke:#c0d8f0;stroke-width:0.5}
  .ena{fill:#d45050;stroke:#f0b0b0;stroke-width:0.5}
  .bdr{fill:none;stroke:#d0d8e0;stroke-width:0.35;pointer-events:none}
  .tip{position:absolute;background:rgba(22,39,58,0.92);border:1px solid #3a6080;
       border-radius:4px;padding:5px 10px;font-size:12px;pointer-events:none;
       display:none;white-space:nowrap}
  #leg{padding:8px 18px;background:#16273a;border-top:1px solid #2a4560;
       display:flex;gap:22px;flex-shrink:0}
  .li{display:flex;align-items:center;gap:7px;font-size:12px}
  .sw{width:13px;height:13px;border-radius:2px}
</style>
</head>
<body>
<div id="hdr"><h1>&#127758; Geography Keyword Builder — Countries</h1>
<p>Colours reflect current On/Off settings in the plugin</p></div>
<div id="mw"><svg id="map"></svg><div class="tip" id="tip"></div></div>
<div id="leg">
  <div class="li"><div class="sw" style="background:#d45050"></div>Enabled (On)</div>
  <div class="li"><div class="sw" style="background:#4a8fd4"></div>Supported (Off)</div>
  <div class="li"><div class="sw" style="background:#9ba8b5"></div>Other</div>
</div>
<script src="https://cdn.jsdelivr.net/npm/d3@7/dist/d3.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/topojson@3/dist/topojson.min.js"></script>
<script>
var SUP=new Set([SUPPORTED_JS]),ENA=new Set([ENABLED_JS]);
var NM={578:"Norway",752:"Sweden",591:"Panama",840:"United States",152:"Chile",404:"Kenya",554:"New Zealand",304:"Greenland",246:"Finland",826:"United Kingdom",356:"India",32:"Argentina",10:"Antarctica",36:"Australia",646:"Rwanda",710:"South Africa",218:"Ecuador",72:"Botswana",100:"Bulgaria",348:"Hungary",528:"Netherlands",156:"China",191:"Croatia",643:"Russia",250:"France",208:"Denmark",352:"Iceland",276:"Germany",724:"Spain",620:"Portugal",380:"Italy",40:"Austria",56:"Belgium",756:"Switzerland",372:"Ireland",616:"Poland",300:"Greece",203:"Czech Republic",642:"Romania",688:"Serbia",703:"Slovakia",705:"Slovenia",233:"Estonia",428:"Latvia",440:"Lithuania",804:"Ukraine",8:"Albania",70:"Bosnia and Herzegovina",499:"Montenegro",807:"North Macedonia",862:"Venezuela",600:"Paraguay",858:"Uruguay",170:"Colombia",604:"Peru",192:"Cuba",320:"Guatemala",84:"Belize",222:"El Salvador",558:"Nicaragua",68:"Bolivia",388:"Jamaica",332:"Haiti",214:"Dominican Republic",44:"Bahamas",328:"Guyana",740:"Surinam",124:"Canada",484:"Mexico",340:"Honduras",188:"Costa Rica",818:"Egypt",504:"Morocco",788:"Tunisia",566:"Nigeria",288:"Ghana",686:"Senegal",834:"Tanzania",231:"Ethiopia",800:"Uganda",516:"Namibia",498:"Moldova",112:"Belarus",792:"Turkey",442:"Luxembourg",470:"Malta",376:"Israel",196:"Cyprus",492:"Monaco",674:"San Marino",438:"Liechtenstein",336:"Vatican City",392:"Japan",764:"Thailand",400:"Jordan",524:"Nepal",144:"Sri Lanka",360:"Indonesia",704:"Vietnam",608:"Philippines",458:"Malaysia",410:"South Korea",116:"Cambodia",784:"United Arab Emirates",242:"Fiji"};
var mw=document.getElementById("mw"),W=mw.clientWidth||window.innerWidth,H=mw.clientHeight||(window.innerHeight-100);
var svg=d3.select("#map").attr("viewBox","0 0 "+W+" "+H).attr("preserveAspectRatio","xMidYMid meet");
svg.append("rect").attr("width",W).attr("height",H).attr("class","ocean");
var proj=d3.geoNaturalEarth1().scale(W/6.3).translate([W/2,H/2]);
var path=d3.geoPath().projection(proj);
var tip=document.getElementById("tip");
d3.json("https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json").then(function(world){
  var countries=topojson.feature(world,world.objects.countries);
  var mesh=topojson.mesh(world,world.objects.countries,function(a,b){return a!==b;});
  svg.append("path").datum(d3.geoGraticule()()).attr("class","grat").attr("d",path);
  svg.selectAll(".c").data(countries.features).join("path")
    .attr("class",function(d){var id=+d.id;return ENA.has(id)?"ena":SUP.has(id)?"sup":"land";})
    .attr("d",path)
    .on("mousemove",function(event,d){
      var id=+d.id,name=NM[id];if(!name)return;
      var lbl=ENA.has(id)?name+" (On)":SUP.has(id)?name+" (Off)":name;
      tip.textContent=lbl;tip.style.display="block";
      tip.style.left=(event.offsetX+14)+"px";tip.style.top=(event.offsetY+10)+"px";
    })
    .on("mouseleave",function(){tip.style.display="none";});
  svg.append("path").datum(mesh).attr("class","bdr").attr("d",path);
}).catch(function(){
  svg.append("text").attr("x",W/2).attr("y",H/2).attr("text-anchor","middle")
    .attr("fill","#e88").text("Could not load map data — check internet connection");
});
</script>
</body></html>
]==]

        html = html:gsub("SUPPORTED_JS", table.concat(supParts,","))
        html = html:gsub("ENABLED_JS",   table.concat(enaParts,","))

        local outPath = LrPathUtils.child( _PLUGIN.path, "lr_geography_map.html" )
        local fh = io.open( outPath, "w" )
        if not fh then return nil end
        fh:write( html ); fh:close()
        return outPath
end

return WorldMap
